﻿import Link from 'next/link'
import { notFound } from 'next/navigation'
import { readStore } from '@/lib/store-db'
export const dynamic='force-dynamic'
export default async function BlogPostPage({params}:{params:Promise<{slug:string}>}){
 const {slug}=await params
 const post=(await readStore()).posts.find(p=>p.slug===slug&&p.status==='published')
 if(!post)notFound()
 return <article className="store-shell"><Link href="/blog" className="text-sm underline">Back to Journal</Link><header className="mx-auto my-12 max-w-4xl text-center"><p className="store-eyebrow">{post.category}</p><h1 className="font-heading text-5xl">{post.title}</h1><p className="mt-6 text-zinc-400">By {post.author} · <time>{post.date}</time></p></header><img src={post.image} alt={post.title} className="mx-auto max-h-[600px] w-full rounded object-cover"/><div className="mx-auto mt-12 max-w-3xl space-y-6 text-lg leading-8 text-zinc-300">{post.content.split(/\n\s*\n/).map((paragraph,index)=><p className="whitespace-pre-wrap" key={index}>{paragraph}</p>)}</div><Link href="/shop" className="store-primary mx-auto mt-12 block w-fit">Explore the Collection</Link></article>
}

﻿import Link from 'next/link'
import { readStore } from '@/lib/store-db'
export const dynamic='force-dynamic'
export default async function BlogPage({searchParams}:{searchParams:Promise<{category?:string}>}){
 const {category}=await searchParams
 const all=(await readStore()).posts.filter(p=>p.status==='published')
 const posts=category?all.filter(p=>p.category===category):all
 return <section className="store-shell"><header className="mb-12 text-center"><p className="store-eyebrow">Stories, culture & craftsmanship</p><h1 className="font-heading text-5xl">The Heritage Journal</h1><p className="mt-5 text-zinc-400">Explore African fashion, fabrics, and the stories behind Adire Teems.</p></header><nav className="mb-10 flex flex-wrap justify-center gap-5"><Link className="text-[#e4c158] underline" href="/blog">All Stories</Link>{Array.from(new Set(all.map(p=>p.category))).map(c=><Link key={c} href={`/blog?category=${encodeURIComponent(c)}`} className="underline">{c}</Link>)}</nav>{!posts.length?<p className="store-panel text-center">New stories are coming soon.</p>:<div className="grid gap-8 md:grid-cols-3">{posts.map(p=><article key={p.id}><Link href={`/blog/${p.slug}`}><img className="aspect-[4/3] w-full rounded object-cover" src={p.image} alt={p.title}/><p className="my-4 text-xs uppercase tracking-widest text-[#e4c158]">{p.category} · {p.date}</p><h2 className="font-heading text-3xl">{p.title}</h2><p className="my-4 text-zinc-400">{p.excerpt}</p><span className="text-sm underline">Read article</span></Link></article>)}</div>}</section>
}

'use client'
import Link from 'next/link'
import { useCart } from '@/components/cart-provider'
import { useCurrency } from '@/components/currency-provider'
import { useStore } from '@/components/store-provider'

export default function CartPage() {
  const { money } = useCurrency()
  const { products } = useStore()
  const { items, ready, update, syncError, retrySync } = useCart()
  const subtotals = items.reduce<Record<string, number>>((totals, item) => {
    const product = products.find(p => p.id === item.productId)
    if (product) { const code = product.currency || 'NGN'; totals[code] = (totals[code] || 0) + product.price * item.quantity }
    return totals
  }, {})
  return <section className="store-shell">
    <Link href="/dashboard" className="mb-5 inline-block text-sm underline">← Your dashboard</Link>
    <p className="store-eyebrow">Your selection</p><h1 className="mb-8 font-heading text-4xl">Shopping Bag</h1>
    {syncError && <p role="alert" className="mb-5 text-amber-300">{syncError} <button onClick={retrySync} className="underline">Retry sync</button></p>}
    {!ready ? <p role="status">Loading your bag…</p> : !items.length ? <div className="store-panel py-16 text-center">
      <h2 className="font-heading text-2xl">Your bag is empty</h2><p className="my-4 text-zinc-400">Explore the collection and find your next favourite piece.</p>
      <Link href="/shop" className="store-primary inline-block">Explore the collection</Link>
    </div> : <div className="grid gap-10 lg:grid-cols-[1.7fr_1fr]"><div>{items.map(item => {
      const product = products.find(p => p.id === item.productId)
      return <article key={`${item.productId}-${item.size}`} className="flex gap-5 border-b border-zinc-700 py-6">
        {product && <Link href={`/product/${product.slug}`}><img src={product.image} alt={product.name} className="h-36 w-24 rounded object-cover sm:w-28" /></Link>}
        <div className="flex-1">{product ? <Link href={`/product/${product.slug}`} className="font-heading text-xl">{product.name}</Link> : <p>Product no longer available. Remove it before checking out.</p>}
          <p className="my-2 text-sm text-zinc-400">Size: {item.size}{product && ` · ${money(product.price, product.currency)} each`}</p>
          <div className="flex flex-wrap items-center gap-4"><label className="text-sm">Quantity <select aria-label={`Quantity for ${product?.name || 'unavailable product'}, size ${item.size}`} value={item.quantity} onChange={e => update(item.productId, item.size, Number(e.target.value))} className="ml-2 border border-zinc-600 bg-[#171717] p-2">{Array.from({ length: 10 }, (_, i) => <option key={i} value={i + 1}>{i + 1}</option>)}</select></label>
            <button onClick={() => update(item.productId, item.size, 0)} className="text-sm text-zinc-400 underline">Remove</button></div>
          {product && <p className="mt-3 text-[#e4c158]">{money(product.price * item.quantity, product.currency)}</p>}
        </div>
      </article>
    })}<Link href="/shop" className="mt-6 inline-block text-sm underline">Continue shopping</Link></div>
      <aside className="store-panel h-fit"><h2 className="mb-6 font-heading text-2xl">Order summary</h2><div className="flex justify-between"><span>Items subtotal</span><span>{Object.entries(subtotals).map(([code, total]) => <span className="block" key={code}>{money(total, code)}</span>)}</span></div>
        <p className="my-5 text-sm text-zinc-400">Delivery and any applicable taxes are confirmed before payment.</p><Link href="/checkout" className="store-primary block text-center">Proceed to checkout</Link></aside>
    </div>}
  </section>
}

'use client'
import Link from 'next/link'
import { DashboardHeader, Title } from '@/components/dashboard-ui'
import { useCustomer } from '@/components/customer-provider'
import { useCart } from '@/components/cart-provider'
import { useStore } from '@/components/store-provider'
import { useCurrency } from '@/components/currency-provider'
import { OrderList } from '@/components/customer-orders'
export default function DashboardPage() {
  const { customer, error } = useCustomer(); const { items, ready, update, syncError, retrySync } = useCart(); const { products } = useStore(); const { money } = useCurrency()
  const count = items.reduce((sum, item) => sum + item.quantity, 0)
  return <><DashboardHeader title={customer?.name ? `Welcome, ${customer.name.split(' ')[0]}` : 'Your dashboard'} />{error && <p role="alert" className="mt-4">{error}</p>}<div className="my-8 grid gap-4 sm:grid-cols-3">{[[`${count} items in your bag`, '/dashboard/cart'], ['Orders & delivery tracking', '/dashboard/orders'], ['Explore the shop', '/shop']].map(([label, href]) => <Link key={href} href={href} className="rounded-lg border border-zinc-300 bg-white p-5 font-semibold">{label} →</Link>)}</div><div className="grid gap-8 xl:grid-cols-2"><section><Title title="Your shopping bag" link="View bag" href="/dashboard/cart" />{syncError && <p role="alert" className="mb-4 text-sm">{syncError} <button onClick={retrySync} className="underline">Retry sync</button></p>}{!ready ? <p>Loading your bag…</p> : !items.length ? <div className="rounded-lg border border-dashed border-zinc-400 p-8"><p>Your bag is empty. Items you add in the shop appear here.</p><Link href="/shop" className="mt-4 inline-block underline">Find your next piece</Link></div> : <div className="rounded-lg border border-zinc-300 bg-white p-5">{items.map(item => { const product = products.find(p => p.id === item.productId); return <article key={`${item.productId}-${item.size}`} className="flex gap-4 border-b border-zinc-200 py-4">{product && <Link href={`/product/${product.slug}`}><img src={product.image} alt={product.name} className="h-24 w-20 rounded object-cover" /></Link>}<div className="min-w-0 flex-1">{product ? <Link href={`/product/${product.slug}`} className="font-semibold">{product.name}</Link> : <p>Product no longer available</p>}<p className="my-2 text-sm">Size {item.size} · Qty {item.quantity}</p>{product && <p className="text-sm">{money(product.price * item.quantity, product.currency)}</p>}<button onClick={() => update(item.productId, item.size, 0)} className="mt-2 text-xs underline">Remove</button></div></article> })}<Link href="/checkout" className="mt-5 block bg-black px-5 py-3 text-center text-white">Continue to checkout</Link></div>}</section><section><Title title="Your orders" link="View all" href="/dashboard/orders" /><OrderList limit={3} /></section></div><section className="mt-8 rounded-lg bg-black p-6 text-white"><h2 className="font-heading text-2xl">Follow your order, every step of the way</h2><p className="my-3 text-zinc-300">Open an order to see preparation, dispatch, the latest delivery location, and arrival updates.</p><Link href="/contact" className="text-[#e4c158] underline">Get help with an order</Link></section></>
}

 'use client'

import { useMemo, useState, useEffect } from 'react'
import Link from 'next/link'
import { ChevronDown, X } from 'lucide-react'
import { useSearchParams } from 'next/navigation'

import { useStore } from '@/components/store-provider'
import { Suspense } from 'react'
import { QuickAdd } from '@/components/product-purchase'
import { useCurrency } from '@/components/currency-provider'
import { styleGroups, matchesStyle } from '@/lib/styles'


const categoryOptions = [['all', 'All Pieces'], ['women', 'Women'], ['men', 'Men'], ['kids', 'Kids'], ['rest', 'Other']] as const

function matchesPrice(price: number, selected: string) {
  if (selected === 'under') return price < 500
  if (selected === 'mid') return price >= 500 && price <= 1000
  if (selected === 'over') return price > 1000
  return true
}

function ShopContent() {
  const { money, currency, toUsd } = useCurrency()
  const priceOptions = [['all', 'All prices'], ['under', 'Under ' + money(500)], ['mid', money(500) + ' - ' + money(1000)], ['over', 'Over ' + money(1000)]]

  const { products: productsSource } = useStore()
  const fabricOptions = ['all', ...Array.from(new Set(productsSource.map(p => p.fabric).filter(Boolean))).sort()]
  const canComparePrices=productsSource.every(p=>toUsd(p.price,p.currency)!==null)
  const [category, setCategory] = useState<string>('all')
  const [styleGroup, setStyleGroup] = useState('')
  const [style, setStyle] = useState('')
  const [price, setPrice] = useState<string>('all')
  const [fabric, setFabric] = useState<string>('all')
  const [sort, setSort] = useState('featured')
  const [query, setQuery] = useState('')
  const [openFilter, setOpenFilter] = useState('')


  const filteredProducts = useMemo(() => {
    const source = productsSource
    const results = source.filter((product) => {
      if (category === 'all') return true
      if(product.department)return category==='rest' ? ['rest','accessories','others'].includes(product.department) : product.department===category
      const name = product.name.toLowerCase()
      const isKids = name.includes('kid') || name.includes('kids')
      const isWomen = ['dresses', 'sets'].includes(product.category)
      const isMen = ['sets', 'robes'].includes(product.category) // best-effort mapping for menswear

      if (category === 'women') return isWomen
      if (category === 'men') return isMen
      if (category === 'kids') return isKids
      if (category === 'rest') return !isWomen && !isMen && !isKids

      return product.category === category
    }).filter((product) => matchesStyle(product, styleGroup, style) && (!canComparePrices || matchesPrice(toUsd(product.price,product.currency)!, price)) && (fabric === 'all' || product.fabric === fabric) && `${product.name} ${product.description} ${product.fabric}`.toLowerCase().includes(query.toLowerCase().trim()))
    return [...results].sort((a, b) => canComparePrices && sort === 'low' ? toUsd(a.price,a.currency)! - toUsd(b.price,b.currency)! : canComparePrices && sort === 'high' ? toUsd(b.price,b.currency)! - toUsd(a.price,a.currency)! : 0)
  }, [category, price, fabric, sort, query, productsSource, styleGroup, style, canComparePrices, toUsd])
  const clearFilters = () => { setCategory('all'); setStyleGroup(''); setStyle(''); setPrice('all'); setFabric('all'); setQuery('') }
  const activeFilters = [styleGroup && (style ? styleGroup + ": " + style : styleGroup),category !== 'all' && categoryOptions.find(([value]) => value === category)?.[1], price !== 'all' && priceOptions.find(([value]) => value === price)?.[1], fabric !== 'all' && fabric].filter(Boolean) as string[]

  // Read category from URL query param and map to internal filters
  const searchParams = useSearchParams()
  useEffect(() => {
    const cat = searchParams?.get('category')
    // Synchronize navigation from the homepage collection links.
    // eslint-disable-next-line react-hooks/set-state-in-effect
    if (cat) setCategory(cat)
  }, [searchParams])

  return <section className="min-h-screen bg-[#0d0d0d] px-4 pb-20 pt-10 text-[#f5f3ef] sm:px-8 lg:px-16 lg:pt-14">
    <div className="mx-auto max-w-[1420px]">
      <div className="mb-7 flex min-h-8 flex-wrap items-center gap-2 lg:pl-[280px]"><span className="mr-3 text-[11px] tracking-[0.12em] text-zinc-500">ACTIVE FILTERS:</span>{activeFilters.length ? activeFilters.map((filter) => <button key={filter} onClick={clearFilters} className="flex items-center gap-1 border border-zinc-500 px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.1em] transition hover:border-[#e4c158] hover:text-[#e4c158]">{filter} <X className="h-3 w-3" /></button>) : <span className="text-sm text-zinc-500">Browse the collection</span>}</div>
      <div className="grid gap-6 lg:grid-cols-[256px_minmax(0,1fr)] lg:gap-7">
        <aside className="flex min-h-0 min-w-0 flex-col self-start overflow-hidden rounded-md border border-zinc-700 bg-[#171717] lg:sticky lg:top-40 lg:max-h-[calc(100dvh-11rem)]">
          <div className="mx-6 flex shrink-0 items-center justify-between border-b border-dashed border-[#b89a25] py-4 lg:py-6"><h1 className="font-heading text-[27px] font-medium">Filters</h1><button onClick={clearFilters} className="text-[11px] font-semibold uppercase tracking-[0.12em] text-zinc-500 hover:text-[#e4c158]">Clear all</button></div>
          <div className="shop-filter-scroll flex min-h-0 flex-wrap gap-2 px-3 py-3 lg:block lg:px-6 lg:py-0 lg:pb-3 focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-[#e4c158]" tabIndex={0} role="region" aria-label="Scroll product filters">
          <FilterGroup title="Category" expanded={openFilter === "category"} onToggle={() => setOpenFilter(openFilter === "category" ? "" : "category")}>{categoryOptions.map(([value, label]) => <CheckOption key={value} label={label} checked={category === value} onChange={() => setCategory(value)} />)}</FilterGroup>
          <FilterGroup title="Styles" expanded={openFilter === "styles"} onToggle={() => setOpenFilter(openFilter === "styles" ? "" : "styles")}><RadioOption label="All styles" checked={!styleGroup} onChange={()=>{setStyleGroup('');setStyle('')}} />{styleGroups.map(group=><details key={group.name} className="border-t border-zinc-700 pt-3"><summary className="cursor-pointer text-sm text-zinc-200">{group.name}{styleGroup===group.name && <span className="ml-2 text-[#e4c158]">(selected)</span>}</summary><div className="mt-3 space-y-3 pl-3"><RadioOption label={'All ' + group.name} checked={styleGroup===group.name && !style} onChange={()=>{setStyleGroup(group.name);setStyle('')}} />{group.styles.map(option=><RadioOption key={option} label={option} checked={styleGroup===group.name && style===option} onChange={()=>{setStyleGroup(group.name);setStyle(option)}} />)}</div></details>)}</FilterGroup>
          {canComparePrices&&<FilterGroup title={`Price (${currency})`} expanded={openFilter === "price"} onToggle={() => setOpenFilter(openFilter === "price" ? "" : "price")}>{priceOptions.map(([value, label]) => <RadioOption key={value} label={label} checked={price === value} onChange={() => setPrice(value)} />)}</FilterGroup>}
          <FilterGroup title="Fabrics" expanded={openFilter === "fabrics"} onToggle={() => setOpenFilter(openFilter === "fabrics" ? "" : "fabrics")}>{fabricOptions.map((value) => <RadioOption key={value} label={value === 'all' ? 'All fabrics' : value} checked={fabric === value} onChange={() => setFabric(value)} />)}</FilterGroup>
          </div>
        </aside>
        <div>
          <label className="mb-5 block text-xs uppercase tracking-widest text-zinc-400">Search collection<input id="search" type="search" value={query} onChange={event => setQuery(event.target.value)} placeholder="Search pieces or fabrics" className="mt-2 block w-full scroll-mt-28 border border-zinc-700 bg-[#171717] p-3 text-sm normal-case tracking-normal text-white" /></label>
          <div className="mb-5 flex items-center justify-between border-b border-zinc-800 pb-4"><p className="text-sm text-zinc-400"><span className="text-[#e4c158]">{filteredProducts.length}</span> pieces selected</p><select disabled={!canComparePrices} value={sort} onChange={(event) => setSort(event.target.value)} className="bg-transparent text-xs uppercase tracking-[0.12em] text-zinc-400 outline-none"><option className="bg-[#171717]" value="featured">Sort: Featured</option><option className="bg-[#171717]" value="low">Price: Low to high</option><option className="bg-[#171717]" value="high">Price: High to low</option></select></div>
          {filteredProducts.length ? <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 xl:grid-cols-3">{filteredProducts.map((product) => <article key={product.id} className="group overflow-hidden rounded-md border border-zinc-700 bg-[#171717] transition duration-300 hover:-translate-y-1 hover:border-zinc-500"><Link href={`/product/${product.slug}`} className="relative block aspect-[3/4] overflow-hidden bg-zinc-800"><img src={product.image} alt={product.name} className="h-full w-full object-cover transition duration-500 group-hover:scale-105" />{product.badge && <span className="absolute left-4 top-4 bg-[#e4c158] px-3 py-1.5 text-[10px] font-semibold uppercase tracking-[0.08em] text-black">{product.badge}</span>}</Link><div className="p-4"><h2 className="text-[15px] font-semibold tracking-[-0.01em]"><Link href={`/product/${product.slug}`}>{product.name}</Link></h2><p className="mt-1 text-sm text-zinc-400">{product.description}</p><div className="mt-4 flex flex-wrap items-center justify-between gap-3"><span className="text-lg font-bold text-[#e4c158]">{money(product.price,product.currency)}</span><QuickAdd product={product} /></div></div></article>)}</div> : <div className="grid min-h-80 place-items-center border border-dashed border-zinc-700 text-center"><div><p className="font-heading text-2xl">No pieces found</p><button onClick={clearFilters} className="mt-3 text-sm text-[#e4c158] underline underline-offset-4">Clear filters</button></div></div>}
          <p className="mt-10 border-t border-zinc-800 pt-6 text-center text-sm text-zinc-400">You have viewed all {filteredProducts.length} pieces</p>
        </div>


      </div>
    </div>
  </section>
}

function FilterGroup({ title, children, expanded, onToggle }: { title: string; children: React.ReactNode; expanded: boolean; onToggle: () => void }) {
  const id = `filter-${title.split(' ')[0].toLowerCase()}`
  return <>
    <button type="button" aria-expanded={expanded} aria-controls={id} onClick={onToggle} className={`flex min-h-11 flex-1 items-center justify-center gap-1 rounded border px-2 py-2 text-xs lg:hidden ${expanded ? 'border-[#e4c158] text-[#e4c158]' : 'border-zinc-600 text-zinc-200'}`}>{title.startsWith("Price") ? "Price" : title}<ChevronDown aria-hidden="true" className={`h-3 w-3 shrink-0 ${expanded ? 'rotate-180' : ''}`} /></button>
    <fieldset id={id} className={`${expanded ? 'block' : 'hidden'} order-1 w-full min-w-0 border-b border-dashed border-[#b89a25] py-4 lg:block lg:py-6`}><legend className="sr-only mb-4 text-[15px] font-semibold lg:not-sr-only">{title}</legend><div className="max-h-72 space-y-3 overflow-y-auto px-2 lg:max-h-none lg:overflow-visible lg:px-0">{children}</div></fieldset>
  </>
}
function CheckOption({ label, checked, onChange }: { label: string; checked: boolean; onChange: () => void }) { return <label className="flex cursor-pointer items-center gap-3 text-sm text-zinc-300"><input type="checkbox" checked={checked} onChange={onChange} className="peer sr-only" /><span className="grid h-4 w-4 place-items-center border border-zinc-500 peer-checked:border-[#e4c158] peer-checked:bg-[#e4c158] peer-checked:text-black">{checked && '✓'}</span>{label}</label> }
function RadioOption({ label, checked, onChange }: { label: string; checked: boolean; onChange: () => void }) { return <label className="flex cursor-pointer items-center gap-3 text-sm text-zinc-300"><input type="radio" checked={checked} onChange={onChange} className="peer sr-only" /><span className="h-4 w-4 rounded-full border border-zinc-500 p-1 peer-checked:border-[#e4c158]"><span className={`block h-full w-full rounded-full ${checked ? 'bg-[#e4c158]' : ''}`} /></span>{label}</label> }

export default function ShopPage(){return <Suspense fallback={<p>Loading shop�</p>}><ShopContent/></Suspense>}

'use client'

import { createContext, useContext, useEffect, useState } from 'react'
import { currencies, formatPrice, validRates, type Currency, type ExchangeRates } from '@/lib/currency'

const CurrencyContext = createContext({ currency: 'USD' as Currency, setCurrency: (_value: Currency) => {}, money: (value: number, source = 'USD') => new Intl.NumberFormat('en-NG',{style:'currency',currency:source}).format(value), toUsd: (value:number,source='USD'):number|null => source==='USD'?value:null, available: false, notice: 'Loading exchange rates…' })
export function CurrencyProvider({ children }: { children: React.ReactNode }) {
  const [currency, select] = useState<Currency>('USD')
  const [data, setData] = useState<ExchangeRates | null>(null)
  const [notice, setNotice] = useState('Loading exchange rates…')
  useEffect(() => {
    let active = true
    async function refresh() {
      let snapshot: ExchangeRates | null = null
      try { const saved = JSON.parse(localStorage.getItem('adire-exchange-rates') || 'null'); if (validRates(saved)) snapshot = saved } catch {}
      try {
        const response = await fetch('/api/exchange-rates')
        const result = await response.json()
        if (!response.ok || !validRates(result)) throw new Error('Unavailable')
        snapshot = result
        try { localStorage.setItem('adire-exchange-rates', JSON.stringify(result)) } catch {}
      } catch {}
      if (!active) return
      if (snapshot) {
        setData(snapshot)
        setNotice(`Approximate conversion · rates dated ${snapshot.date}`)
        try { const saved = localStorage.getItem('adire-currency') as Currency; if (currencies.includes(saved)) select(saved) } catch {}
      } else setNotice('Exchange rates unavailable. Prices shown in their original currency.')
    }
    void refresh()
    const timer = setInterval(refresh, 3600000)
    return () => { active = false; clearInterval(timer) }
  }, [])
  const setCurrency = (value: Currency) => {
    if (value !== 'USD' && !data) return
    select(value)
    try { localStorage.setItem('adire-currency', value) } catch {}
  }
  return <CurrencyContext.Provider value={{ currency, setCurrency, money: (value,source='USD') => { const rate=data?.rates[source as Currency]; return rate ? formatPrice(value,currency,data!.rates[currency]/rate) : new Intl.NumberFormat('en-NG',{style:'currency',currency:source}).format(value) }, toUsd: (value,source='USD') => source==='USD'?value:data?.rates[source as Currency]?value/data.rates[source as Currency]:null, available: !!data, notice }}>{children}</CurrencyContext.Provider>
}
export const useCurrency = () => useContext(CurrencyContext)
export function CurrencySelector() {
  const { currency, setCurrency, available, notice } = useCurrency()
  return <div className="flex flex-wrap items-center gap-3 text-xs"><label className="flex items-center gap-2 text-zinc-300">Currency<select aria-label="Display currency" value={currency} onChange={event => setCurrency(event.target.value as Currency)} className="rounded border border-zinc-600 bg-[#171717] p-2 text-[#e4c158]">{currencies.map(code => <option key={code} value={code} disabled={code !== 'USD' && !available}>{code}</option>)}</select></label><span className="text-zinc-400" role="status">{notice}</span></div>
}

